FILE 2 — `assets/sim/signin.js` (stock submit handler):

```js
// Stock submit handler for generic-signin. Contract: POST to the SAME url that
// served the page (token rides in path/query). Server records a boolean-only
// event, never the payload, then hands back a redirect destination.
(function () {
  var form = document.getElementById('signin-form');
  var btn  = document.getElementById('submit-btn');
  var msg  = document.getElementById('form-msg');
  var fellBack = false;                       // one-shot native fallback guard

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (form.dataset.busy === '1') return;    // no double submits
    form.dataset.busy = '1';
    btn.disabled = true;
    btn.textContent = 'Signing in…';          // mimic real auth latency

    var body = new URLSearchParams(new FormData(form)).toString();

    fetch(window.location.pathname + window.location.search, {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8'
      },
      body: body,
      credentials: 'same-origin'
    })
    .then(function (res) { if (!res.ok) throw new Error('HTTP ' + res.status); return res.json(); })
    .then(function (data) {
      // Server owns destination: training page, retry slip (?e=1), next step…
      window.location.assign(data.redirect || '/sim/unavailable');
    })
    .catch(function () {
      // Network flake: native POST once — server replies 302. No-JS path too.
      if (fellBack) { msg.textContent = 'Something went wrong. Try again.'; return; }
      fellBack = true;
      form.submit();
    });
  });

  // Inert affordances (forgot-password…) — route to decoy page in prod.
  document.querySelectorAll('[data-sim-inert]').forEach(function (el) {
    el.addEventListener('click', function (ev) { ev.preventDefault(); });
  });
})();
```

ROUTE 3 — capture endpoint (same URL serves page on GET, consumes submit on POST):

```js
// app.all('/p/:slug') — one route, both methods, single source of truth
app.all('/p/:slug', async (req, res) => {
  const send = await sends.byToken(req.query.t);            // per-recipient token
  if (!send || send.state !== 'active') return res.redirect('/sim/expired');

  if (req.method === 'GET') {
    return res.render('generic-signin', buildCtx(send));    // merge-field substitution
  }

  // ---- POST: only moment participant input exists, anywhere ----
  const flags = {                                           // booleans derived in memory
    email:    !!req.body.email,
    password: !!req.body.password,
    step:     Number(req.body.step) || 1
  };
  req.body = null;                                          // DISCARD. no persist, no log.

  await events.insert({                                     // boolean-only event row
    ts: new Date().toISOString(),
    type: 'form_submitted',
    sendId: send.id, campaignId: send.campaignId, recipientId: send.recipientId,
    flags,
    ipHash: hashIp(req.ip),                                 // raw / hashed / off — config
    ua: req.get('user-agent') || null
  }, { idempotencyKey: send.id + ':form_submitted' });      // replay-safe

  await risk.recompute(send.recipientId);                   // async queue in prod
  await bus.emit('sim.event', { type: 'form_submitted', sendId: send.id }); // → SIEM/training

  const dest = `/p/${send.slug}/training?t=${send.token}`;
  return req.accepts(['html', 'json']) === 'json'
    ? res.json({ ok: true, redirect: dest })                // XHR path (our fetch)
    : res.redirect(302, dest);                              // native POST path (no-JS)
});
```

GOTCHAS:
- Token = identity. Lives in URL; hidden fields carry only step/tpl. ⊥ trust any hidden user id — resolve server-side ∀ request.
- Same origin only. Submit hits sim host, ⊥ admin host → no CORS, clean history.
- Payload dies in handler: read → booleans → `req.body = null`. Crash dumps included. Test: submit `hunter2` → grep DB + logs → zero hits. That grep = your vendor-proof test.
- Idempotency key = sendId + type → double clicks / back-button replays ⊥ double count.
- `?e=1` variant = "wrong password" second attempt, raises submit realism. Reveal redirect closes loop → training-completion event.
- Multi-step (email → password → OTP): same component, `step` increments, server returns next-step redirect. One file, n steps.
- Password-manager autofill can flip password boolean without typing — record anyway; add interaction-timing field if vendor deltas matter.
- a11y stays: labels, aria-live, focus ring — accessible sims more convincing, ⊥ less.
- a11y, robots noindex, view-source survival, realistic field names — all part of the stock component QA checklist.

