Test run: 33 passed, 0 failed — classic test PANs across visa / mastercard (5- and 2-series) / amex / discover / jcb / diners / unionpay, bad checksums, expiry edges (current month valid, last month rejected), amex 4-digit CVC, and both formatters.

------- card-validation.mjs -------

// Client-side validation for a checkout card form: Luhn, expiry, CVC, card type.
// UX only — passing these checks does not mean a card is valid; the processor
// authorizes. In production prefer hosted fields (Stripe Elements, Razorpay,
// Adyen) so card data never touches your DOM.

const NON_DIGITS = /\D+/g;
const toDigits = (v) => String(v ?? '').replace(NON_DIGITS, '');

// ---- Brand / type detection ----------------------------------------------

function isMastercardRange(d) {
  if (/^5[1-5]/.test(d)) return true;
  return d.length >= 4 && +d.slice(0, 4) >= 2221 && +d.slice(0, 4) <= 2720;
}

export const BRANDS = [
  { id: 'amex',       name: 'American Express', lengths: [15],              gaps: [4, 10],        cvc: 4, test: (d) => /^3[47]/.test(d) },
  { id: 'visa',       name: 'Visa',             lengths: [13, 16, 19],      gaps: [4, 8, 12, 16], cvc: 3, test: (d) => /^4/.test(d) },
  { id: 'mastercard', name: 'Mastercard',       lengths: [16],              gaps: [4, 8, 12],     cvc: 3, test: isMastercardRange },
  { id: 'discover',   name: 'Discover',         lengths: [16, 19],          gaps: [4, 8, 12, 16], cvc: 3, test: (d) => /^(6011|65|64[4-9]|622(12[6-9]|1[3-9]\d|[2-8]\d\d|9[01]\d|92[0-5]))/.test(d) },
  { id: 'jcb',        name: 'JCB',              lengths: [16, 17, 18, 19],  gaps: [4, 8, 12, 16], cvc: 3, test: (d) => /^35(2[89]|[3-8]\d)/.test(d) },
  { id: 'diners',     name: 'Diners Club',      lengths: [14, 16, 19],      gaps: [4, 10],        cvc: 3, test: (d) => /^(30[0-5]|3095|3[689])/.test(d) },
  { id: 'unionpay',   name: 'UnionPay',         lengths: [16, 17, 18, 19],  gaps: [4, 8, 12, 16], cvc: 3, test: (d) => /^62/.test(d) },
];

export const UNKNOWN_BRAND = {
  id: 'unknown',
  name: 'Card',
  lengths: [12, 13, 14, 15, 16, 17, 18, 19],
  gaps: [4, 8, 12, 16],
  cvc: 3,
};

export function detectBrand(input) {
  const digits = toDigits(input);
  return BRANDS.find((b) => b.test(digits)) ?? UNKNOWN_BRAND;
}

// ---- Luhn checksum ---------------------------------------------------------

export function luhnCheck(input) {
  const digits = toDigits(input);
  if (digits.length === 0) return false;

  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }
  return sum % 10 === 0;
}

// ---- Field validators --------------------------------------------------------

const fail = (code, message) => ({ valid: false, code, message });

export function validateNumber(input) {
  const digits = toDigits(input);
  if (!digits) return fail('empty', 'Enter your card number.');

  const brand = detectBrand(digits);
  if (!brand.lengths.includes(digits.length)) {
    return fail('length', 'That card number looks incomplete or too long.');
  }
  if (!luhnCheck(digits)) {
    return fail('luhn', "That number doesn't pass the checksum — double-check it.");
  }
  return { valid: true, code: 'ok', brand: brand.id };
}

// A card is valid through the END of its expiry month, so the current month
// still passes. Accepts "MMYY" or "MMYYYY" once separators are stripped.
export function validateExpiry(input, now = new Date()) {
  const digits = toDigits(input);
  if (!digits) return fail('empty', 'Enter the expiry date.');

  let mm;
  let yyyy;
  if (digits.length === 4) {
    mm = +digits.slice(0, 2);
    yyyy = 2000 + +digits.slice(2);
  } else if (digits.length === 6) {
    mm = +digits.slice(0, 2);
    yyyy = +digits.slice(2);
  } else {
    return fail('format', 'Use MM / YY.');
  }

  if (mm < 1 || mm > 12) return fail('month', 'Month must be 01–12.');

  const nowIndex = now.getFullYear() * 12 + (now.getMonth() + 1);
  const expiryIndex = yyyy * 12 + mm;
  if (expiryIndex < nowIndex) return fail('past', 'That expiry date is in the past.');

  return { valid: true, code: 'ok', mm, yyyy };
}

export function validateCvc(input, needed = 3) {
  const digits = toDigits(input);
  if (!digits) return fail('empty', 'Enter the security code.');
  if (digits.length !== needed) {
    return fail('length', `That card's security code is ${needed} digits.`);
  }
  return { valid: true, code: 'ok' };
}

// ---- Whole-form check --------------------------------------------------------

export function validateCard({ number, expiry, cvc }, now = new Date()) {
  const brand = detectBrand(number);
  const numberResult = validateNumber(number);
  const expiryResult = validateExpiry(expiry, now);
  const cvcResult = validateCvc(cvc, brand.cvc);
  return {
    valid: numberResult.valid && expiryResult.valid && cvcResult.valid,
    brand: brand.id,
    number: numberResult,
    expiry: expiryResult,
    cvc: cvcResult,
  };
}

// ---- Live formatting (for input events) ---------------------------------------

// Groups per brand (amex 4-6-5, most others in 4s) while typing; digits over
// the brand's max length are dropped.
export function formatCardNumber(input) {
  const brand = detectBrand(input);
  const max = Math.min(Math.max(...brand.lengths), 19);
  const digits = toDigits(input).slice(0, max);

  let out = '';
  for (let i = 0; i < digits.length; i++) {
    out += digits[i];
    if (brand.gaps.includes(i + 1) && i + 1 < digits.length) out += ' ';
  }
  return out;
}

// "1227" -> "12 / 27". Typing is MM-first: three digits renders as "12 / 7",
// so single-digit months need a leading zero ("0127").
export function formatExpiry(input) {
  const digits = toDigits(input).slice(0, 4);
  if (digits.length <= 2) return digits;
  return digits.slice(0, 2) + ' / ' + digits.slice(2);
}

