THE SEQUENCE — who talks to whom

  CLIENT (your page)                 YOUR SERVER                    RAZORPAY
  page load ───────────────────────▶ POST /api/orders ────────────▶ Orders API (key_secret)
      ◀─ order_id stored ──────────────────────────────────────────  order created
  [Pay] click
    validate()
    razorpay.createPayment(card[…]) ─────────────────────────────▶ card / OTP / 3DS flow
      ◀─ payment.success(payment_id, order_id, signature) ◀────────
    POST /api/payments/verify ─────▶ HMAC-SHA256(order|payment)
      ◀─ {status:"verified"} ◀────── fulfil (or defer to capture)
  [later]                          ◀─ webhook payment.captured ◀──  source of truth

Card fields touch: the form, then the SDK call. Nowhere else. Ever.

Client handler — /home/ubuntu/store-checkout/razorpay-submit-handler.js (full):

/**
 * razorpay-submit-handler.js — canonical client-side submit handler for the card checkout.
 * Pairs with card-checkout.html (Custom Checkout UI) and server-example.js.
 *
 * Reference: https://razorpay.com/docs/developer-tools/integrations/custom-checkout/
 *
 * Sequence this implements:
 *   page load   → CheckoutFlow.boot({...})       → POST /api/orders (YOUR server) → order_id stored
 *   [Pay] click → CheckoutFlow.handleSubmit(...) → razorpay.createPayment(card[...])   (card data → Razorpay SDK)
 *   success     → POST /api/payments/verify      → server HMAC-verifies → only then tell the customer "paid"
 *   error       → show message, allow retry on the SAME order_id
 *
 * Hard rules baked in:
 *   - Card fields are NEVER sent to your own server. Up front: {amount, receipt}.
 *     After success: {payment_id, order_id, signature}. Nothing else, ever.
 *   - createPayment must run inside the click (popup/OTP windows need the user gesture),
 *     so the order is created at page load — no await sits between click and createPayment.
 *   - "Verified" is decided by YOUR server, not this file. Browser responses are forgeable.
 */
(function (global) {
  'use strict';

  var CONFIG = {
    keyId:     'rzp_test_REPLACE_ME',   // Dashboard -> API Keys. Key ID is public by design.
    orderUrl:  '/api/orders',           // your server: creates the Razorpay order
    verifyUrl: '/api/payments/verify'   // your server: HMAC-verifies the response
  };

  var state = {
    orderId: null,                      // set by boot()
    amount:  null,                      // paise; must equal the server order amount
    customer: { email: '', contact: '' },
    busy: false                         // in-flight guard (double-submit protection)
  };

  var currentUi = null;

  // ── Razorpay SDK: instantiate once, register result handlers ONCE ──────
  var razorpay = new Razorpay({ key: CONFIG.keyId });

  razorpay.once('ready', function (res) {
    // Render only the methods enabled on the account: res.methods.
    // If this never fires (adblock/CSP), fall back to a minimal set and let the user retry.
  });

  razorpay.on('payment.success', onSuccess);

  razorpay.on('payment.error', function (resp) {
    if (!currentUi) return;
    var err = (resp && resp.error) || {};
    state.busy = false;
    currentUi.setBusy(false);
    currentUi.showError(err.description || 'Payment failed — please try again.');
    // Log the full object for support: err.code, err.step, err.reason,
    // err.metadata && (err.metadata.order_id / err.metadata.payment_id). Never log card data.
  });

  // ── Boot: create the order BEFORE the user clicks Pay ──────────────────
  //     Re-run this if the cart/amount changes (order amount must match exactly).
  //     On rejection: state.orderId stays null; show a retry affordance.
  function boot(opts) {
    state.amount = opts.amount;
    state.customer.email   = (opts.customer && opts.customer.email)   || '';
    state.customer.contact = (opts.customer && opts.customer.contact) || '';
    return global.fetch(CONFIG.orderUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ amount: opts.amount, receipt: opts.receipt })
    })
      .then(function (r) {
        if (!r.ok) throw new Error('order http ' + r.status);
        return r.json();
      })
      .then(function (j) {
        if (!j || !j.order_id) throw new Error('order bootstrap failed');
        state.orderId = j.order_id;                   // e.g. "order_DBJOWzybf0sJbb"
        return state.orderId;
      });
  }

  // ── Submit path — call from your form submit AFTER validate() passes ───
  function handleSubmit(e, payload, ui) {
    if (e && e.preventDefault) e.preventDefault();
    currentUi = ui;

    if (state.busy) return;                           // payment already in flight
    if (!state.orderId || !state.amount) {
      ui.showError('Payment is still initialising — try again in a second.');
      return;
    }

    state.busy = true;
    ui.setBusy(true);

    // Must be called inside the user action — no awaits above this line.
    razorpay.createPayment({
      amount: state.amount,                           // paise; must equal the order amount
      currency: 'INR',
      email: state.customer.email,
      contact: state.customer.contact,
      order_id: state.orderId,
      method: 'card',
      'card[name]':         payload.name,
      'card[number]':       payload.number,           // digits only, straight from the form
      'card[expiry_month]': payload.expiryMonth,
      'card[expiry_year]':  payload.expiryYear,
      'card[cvv]':          payload.cvv
    });
  }

  // ── Success → ask YOUR server, trust only its verdict ──────────────────
  function onSuccess(resp) {
    if (resp.razorpay_order_id !== state.orderId) {
      // Shouldn't happen; refuse anyway. Server always sides with its own records.
      state.busy = false;
      currentUi.setBusy(false);
      currentUi.showError('Something is off with this payment — contact support.');
      return;
    }
    global.fetch(CONFIG.verifyUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        razorpay_payment_id: resp.razorpay_payment_id,
        razorpay_order_id:   resp.razorpay_order_id,
        razorpay_signature:  resp.razorpay_signature
      })
    })
      .then(function (r) {
        if (!r.ok) throw new Error('verify http ' + r.status);
        return r.json();
      })
      .then(function (j) {
        if (j && j.status === 'verified') {
          currentUi.showSuccess('Payment successful.');
        } else {
          currentUi.showError('We could not verify this payment. If money left your account it will be auto-refunded — contact support.');
        }
      })
      .catch(function () {
        // Network hiccup or slow server. The webhook is the source of truth and will
        // reconcile — tell the customer not to pay again.
        currentUi.showInfo('Payment received — confirmation is taking a little longer than usual. Do not pay again; we will confirm by email.');
      })
      .finally(function () {
        state.busy = false;
        currentUi.setBusy(false);
      });
  }

  global.CheckoutFlow = {
    boot: boot,
    handleSubmit: handleSubmit,
    _state: state,
    _config: CONFIG
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = global.CheckoutFlow;
})(typeof window !== 'undefined' ? window : globalThis);

Splice notes (in the file footer): boot on page load with final cart amount; in the submit listener replace the demo `submitToRazorpay` with `CheckoutFlow.handleSubmit(e, payload, ui)`; ui = { setBusy, showError, showInfo, showSuccess }.

