// signature = HMAC_SHA256(key_secret, `${order_id}|${payment_id}`)
function paymentSignature(orderId, paymentId, keySecret) {
  return crypto.createHmac('sha256', keySecret).update(orderId + '|' + paymentId).digest('hex');
}
function safeEqualHex(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const ba = Buffer.from(a, 'hex');
  const bb = Buffer.from(b, 'hex');
  if (ba.length === 0 || ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

app.post('/api/payments/verify', express.json(), async (req, res) => {
  const { razorpay_payment_id, razorpay_order_id, razorpay_signature } = req.body;
  const order = await findOrderByRazorpayId(razorpay_order_id);   // YOUR DB
  if (!order) return res.status(400).json({ status: 'failed', reason: 'unknown_order' });
  const ok = verifyPayment({
    orderId: order.razorpay_order_id,      // id YOU stored — not the browser's value
    paymentId: razorpay_payment_id,
    signature: razorpay_signature,
    keySecret: KEY_SECRET
  });
  if (!ok) return res.status(400).json({ status: 'failed', reason: 'bad_signature' });
  await markOrderPaid(razorpay_order_id, razorpay_payment_id);
  res.json({ status: 'verified' });
});

app.post('/api/webhooks/razorpay', express.raw({ type: '*/*' }), (req, res) => {
  const sig = req.get('X-Razorpay-Signature');
  if (!verifyWebhook({ rawBody: req.body, signature: sig, webhookSecret: WEBHOOK_SECRET }))
    return res.sendStatus(400);
  const event = JSON.parse(req.body.toString());
  if (event.event === 'payment.captured') { /* idempotent: dedupe, mark paid, fulfil once */ }
  res.sendStatus(200);
});

(+ POST /api/orders in the file — creates the Order via the official SDK, key_secret server-only.)

RULES THE SEQUENCING ENFORCES

- Order first, always. No order_id = payment auto-refunded. Amount in paise, must match exactly; recompute it from YOUR cart, not the browser.
- Gesture hygiene: createPayment sits directly in the click — that's why the order is fetched on page load, not in the handler. Await between click and popup = blocked popups on Safari.
- Retry policy: same order_id for a retry after failure; boot() again only if amount/cart changed.
- Verify before you believe: browser success event proves nothing — HMAC on your server does. Timing-safe compare; order_id from your DB.
- Webhook = truth for fulfilment (the customer may close the tab mid-verify). Raw body for its signature, ack in <5s, dedupe by payment id.
- Capture: flip on auto-capture in Dashboard → Account & Settings → Payment Capture, or uncaptured payments bounce back as refunds.
- Key Secret never leaves the server. Card fields never logged, never POSTed by you. That combination is what keeps PCI scope with Razorpay instead of you.

Test evidence: 20/20 handler-flow assertions (fake SDK + fake fetch) — including "no network during submit" and "verify body = exactly the 3 receipt fields"; 11/11 signature assertions (valid passes; tampered/duplicate/wrong-secret/garbage all rejected without throwing).

Standard Checkout flavor, same sequence: swap `razorpay.createPayment({...})` for `var rzp = new Razorpay({ key, order_id, handler }); rzp.open();` — rest identical.

