<!--
  Sandbox card-entry page (internal test harness).
  - Test cards only (see the payment test-card matrix). Never enter real card details.
  - Opened standalone (file://): submit simulates success so the page is drivable without a server.
  - Served behind the app: POSTs to ENDPOINT below — wire it to your sandbox backend.
  - Go-live swap (Stripe Elements example) is at the bottom of this file. Keep ids + classes so styling survives.
-->
<style>
  :root{
    --bg:#f4f5f7; --panel:#ffffff; --ink:#16181d; --muted:#5c6270; --line:#d9dce3;
    --accent:#3b5bfd; --danger:#c2334a; --ok:#0d7a43; --radius:10px;
  }
  *{box-sizing:border-box}
  body{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--bg);color:var(--ink);
       font:15px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}
  .panel{width:min(420px,92vw);background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);
         padding:28px;box-shadow:0 10px 30px rgba(16,20,30,.08)}
  h1{margin:0 0 4px;font-size:19px;font-weight:650}
  .sub{margin:0 0 20px;color:var(--muted);font-size:13px}
  .field{margin-bottom:14px}
  label{display:block;font-size:12.5px;font-weight:600;letter-spacing:.02em;margin-bottom:6px;color:#343945}
  .row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
  input{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:8px;font:inherit;background:#fff;color:inherit}
  input:focus{outline:2px solid var(--accent);outline-offset:1px;border-color:var(--accent)}
  input[aria-invalid="true"]{border-color:var(--danger)}
  .hint{font-size:11.5px;color:var(--muted);font-weight:400}
  .err{font-size:12px;color:var(--danger);margin:5px 0 0}
  .brand{font-size:11px;font-weight:700;letter-spacing:.06em;color:var(--muted);text-transform:uppercase;margin:5px 0 0;height:14px}
  button{width:100%;margin-top:8px;padding:12px;border:0;border-radius:8px;background:var(--accent);color:#fff;
         font:inherit;font-weight:650;cursor:pointer}
  button:disabled{opacity:.55;cursor:not-allowed}
  #status{margin:14px 0 0;font-size:12.5px;color:var(--muted);min-height:18px}
  #status.ok{color:var(--ok)} #status.bad{color:var(--danger)}
</style>
</head>
<body>
<main class="panel">
  <h1>Payment details</h1>
  <p class="sub">Sandbox environment — test cards only.</p>

  <form id="checkout-form" novalidate autocomplete="on">
    <div class="field">
      <label for="card-name">Name on card</label>
      <input id="card-name" name="card_name" type="text" autocomplete="cc-name"
             data-testid="card-name" placeholder="Alex Doe">
      <p class="err" id="err-name" role="alert"></p>
    </div>

    <div class="field">
      <label for="card-number">Card number</label>
      <input id="card-number" name="card_number" type="text" inputmode="numeric" autocomplete="cc-number"
             spellcheck="false" autocapitalize="off" data-testid="card-number"
             placeholder="1234 5678 9012 3456" maxlength="23">
      <p class="brand" id="brand" aria-live="polite"></p>
      <p class="err" id="err-number" role="alert"></p>
    </div>

    <div class="row">
      <div class="field">
        <label for="card-exp">Expiry</label>
        <input id="card-exp" name="card_exp" type="text" inputmode="numeric" autocomplete="cc-exp"
               spellcheck="false" data-testid="card-exp" placeholder="MM / YY" maxlength="7">
        <p class="err" id="err-exp" role="alert"></p>
      </div>
      <div class="field">
        <label for="card-cvc">CVC</label>
        <input id="card-cvc" name="card_cvc" type="text" inputmode="numeric" autocomplete="cc-csc"
               spellcheck="false" data-testid="card-cvc" placeholder="123" maxlength="4">
        <p class="err" id="err-cvc" role="alert"></p>
      </div>
    </div>

    <div class="field">
      <label for="card-postal">Postal code <span class="hint">(optional — AVS scenarios)</span></label>
      <input id="card-postal" name="card_postal" type="text" autocomplete="postal-code"
             data-testid="card-postal" placeholder="560001">
      <p class="err" id="err-postal" role="alert"></p>
    </div>

    <button id="submit-btn" type="submit" data-testid="pay-button">Pay</button>
    <p id="status" aria-live="polite"></p>
  </form>
</main>

<script>
(() => {
  'use strict';

  // Wire this to your sandbox backend (create intent / tokenize / verify).
  const ENDPOINT = '/api/checkout/sandbox';

  const $ = (id) => document.getElementById(id);
  const digits = (s) => (s || '').replace(/\D+/g, '');

  const BRANDS = [
    { name: 'AMEX',       re: /^3[47]/,           groups: [4, 6, 5],    cvc: 4 },
    { name: 'DINERS',     re: /^3(0[0-5]|[689])/, groups: [4, 6, 4],    cvc: 3 },
    { name: 'JCB',        re: /^35(2[89]|[3-8])/, groups: [4, 4, 4, 4], cvc: 3 },
    { name: 'UNIONPAY',   re: /^62/,              groups: [4, 4, 4, 4], cvc: 3 },
    { name: 'DISCOVER',   re: /^6(011|5|4[4-9])/, groups: [4, 4, 4, 4], cvc: 3 },
    { name: 'MASTERCARD', re: /^(5[1-5]|2[2-7])/, groups: [4, 4, 4, 4], cvc: 3 },
    { name: 'VISA',       re: /^4/,               groups: [4, 4, 4, 4], cvc: 3 }
  ];

  const fields = {
    name: $('card-name'),
    number: $('card-number'),
    exp: $('card-exp'),
    cvc: $('card-cvc'),
    postal: $('card-postal')
  };

  const detectBrand = (num) => BRANDS.find((b) => b.re.test(num)) || null;

  function group(d, groups){
    const out = []; let i = 0;
    for (const g of groups){ if (i >= d.length) break; out.push(d.slice(i, i + g)); i += g; }
    if (i < d.length) out.push(d.slice(i));
    return out.join(' ');
  }

  const formatNumber = (v) => {
    const d = digits(v).slice(0, 19);
    const b = detectBrand(d);
    return group(d, b ? b.groups : [4, 4, 4, 4]);
  };

  const formatExp = (v) => {
    const d = digits(v).slice(0, 4);
    return d.length <= 2 ? d : d.slice(0, 2) + ' / ' + d.slice(2);
  };

  function luhn(num){
    const d = digits(num);
    if (d.length < 12) return false;
    let sum = 0, alt = false;
    for (let i = d.length - 1; i >= 0; i--){
      let n = +d[i];
      if (alt){ n *= 2; if (n > 9) n -= 9; }
      sum += n; alt = !alt;
    }
    return sum % 10 === 0;
  }

  function expValid(v){
    const d = digits(v);
    if (d.length !== 4) return false;
    const mm = +d.slice(0, 2), yy = +d.slice(2);
    if (mm < 1 || mm > 12) return false;
    const now = new Date(), cy = now.getFullYear() % 100, cm = now.getMonth() + 1;
    return yy > cy || (yy === cy && mm >= cm);
  }

  function setError(key, msg){
    const el = $('err-' + key);
    if (el) el.textContent = msg || '';
    if (fields[key]) fields[key].setAttribute('aria-invalid', msg ? 'true' : 'false');
  }

  function validate(){
    let ok = true;

    if (!fields.name.value.trim()){ setError('name', 'Enter the name on the card.'); ok = false; }
    else setError('name', '');

    const num = digits(fields.number.value);
    const brand = detectBrand(num);
    if (num.length < 12){ setError('number', 'Enter the card number.'); ok = false; }
    else if (!luhn(num)){ setError('number', 'That number fails the checksum — check for typos.'); ok = false; }
    else setError('number', '');

    if (!expValid(fields.exp.value)){ setError('exp', 'Enter a valid future expiry (MM / YY).'); ok = false; }
    else setError('exp', '');

    const cvc = digits(fields.cvc.value);
    const cvcOk = brand && brand.cvc === 4 ? cvc.length === 4 : (cvc.length === 3 || cvc.length === 4);
    if (!cvcOk){ setError('cvc', 'Enter the ' + (brand && brand.cvc === 4 ? '4' : '3') + '-digit CVC.'); ok = false; }
    else setError('cvc', '');

    setError('postal', '');
    return ok;
  }

  fields.number.addEventListener('input', () => {
    fields.number.value = formatNumber(fields.number.value);
    const b = detectBrand(digits(fields.number.value));
    $('brand').textContent = b ? b.name : '';
  });

  fields.exp.addEventListener('input', () => { fields.exp.value = formatExp(fields.exp.value); });
  fields.cvc.addEventListener('input', () => { fields.cvc.value = digits(fields.cvc.value).slice(0, 4); });

  $('checkout-form').addEventListener('submit', async (e) => {
    e.preventDefault();
    const status = $('status');
    status.className = '';

    if (!validate()){
      status.textContent = 'Fix the highlighted fields.';
      status.className = 'bad';
      const firstBad = document.querySelector('input[aria-invalid="true"]');
      if (firstBad) firstBad.focus();
      return;
    }

    // Sandbox-only payload: the backend tokenizes, then discards. In production
    // the PAN must never reach your server — use processor field mounts instead.
    const payload = {
      card_number: digits(fields.number.value),
      card_exp: digits(fields.exp.value),
      card_cvc: digits(fields.cvc.value),
      card_name: fields.name.value.trim(),
      postal_code: fields.postal.value.trim() || undefined,
      amount: 50000,            // paise/cents — override per test scenario
      currency: 'INR'
    };

    // Standalone preview: simulate so the page is drivable anywhere.
    if (location.protocol === 'file:'){
      status.textContent = 'Sandbox: simulated success for …' + payload.card_number.slice(-4) + ' (no request sent).';
      status.className = 'ok';
      return;
    }

    try {
      const res = await fetch(ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.message || ('HTTP ' + res.status));
      status.textContent = 'Payment submitted — status: ' + (data.status || 'accepted');
      status.className = 'ok';
    } catch (err){
      status.textContent = 'Sandbox endpoint unreachable (' + err.message + ') — check the backend is running.';
      status.className = 'bad';
    }
  });

  // Handy for console-driven test runs and for wiring automated checks.
  window.SandboxForm = { formatNumber, formatExp, luhn, detectBrand, validate };
})();
</script>

